102	export const KnowledgeMoveBodySchema = z
103	  .object({
104	    source_scope: InsightScope,
105	    source_repository_name: z.string().regex(PROJECT_SLUG_REGEX).optional(),
106	    repository_name: z.string().regex(PROJECT_SLUG_REGEX),
107	  })
108	  .strict();
109	
110	// ---------------------------------------------------------------------------
111	// Knowledge — private helpers
112	// ---------------------------------------------------------------------------
113	
114	/**
115	 * Parses a raw string as a positive integer insight ID.
116	 *
117	 * Rejects:
118	 * - Non-numeric strings (NaN after Number())
119	 * - Floating-point strings (any string containing '.', e.g. "1.5", "2.0")
120	 * - Zero or negative integers
121	 *
122	 * The decimal-point check is performed on the raw string before numeric
123	 * coercion so that "2.0" (which coerces to an integer) is still rejected.
124	 *
125	 * @throws ApiError VALIDATION_ERROR for any rejected value.
126	 */
127	export function parseKnowledgeId(raw: string): number {
128	  // Reject strings containing a decimal point before numeric coercion —
129	  // this catches "1.5" and also "2.0", both of which the caller must treat
130	  // as non-integer IDs even though Number("2.0") === 2.
131	  if (raw.includes('.')) {
132	    throw new ApiError('VALIDATION_ERROR', 'Invalid insight id.');
133	  }
134	  const n = Number(raw);
135	  if (!Number.isInteger(n) || n <= 0) {
136	    throw new ApiError('VALIDATION_ERROR', 'Invalid insight id.');
137	  }
138	  return n;
139	}
140	
141	// ---------------------------------------------------------------------------
142	// Interface definitions
143	// ---------------------------------------------------------------------------
144	
145	/** Raw query parameters accepted by GET /api/knowledge. */
146	export interface KnowledgeListParams {
147	  scope?: string;
148	  category?: string;
149	  /** Comma-separated list of tags to filter by. */
150	  tags?: string;
151	  repository_name?: string;
152	  /** Full-text search query — delegates to searchInsights when present. */
153	  query?: string;
154	  limit?: number | string;
155	  offset?: number | string;
156	}
157	
158	// ---------------------------------------------------------------------------
159	// GET /api/knowledge
160	// ---------------------------------------------------------------------------
161	
162	/**
163	 * Lists (or searches) knowledge insights stored in the ledger's `.knowledge/` directory.
164	 *
165	 * - When `query` is present, delegates to `KnowledgeStoreManager.searchInsights()`.
166	 * - Otherwise calls `KnowledgeStoreManager.listInsights()` with scope/category/tags filters.
167	 * - `scope` is validated via `InsightScope.safeParse()`; unrecognised values throw
168	 *   `VALIDATION_ERROR`. Omitting `scope` (or passing `undefined`) returns all insights.
169	 * - `tags` is a comma-separated string that is split before being forwarded.
170	 * - `limit` and `offset` are coerced to non-negative integers; invalid/missing values
171	 *   are silently ignored (limit → undefined, offset → 0).
172	 * - `limit=0` is treated as unlimited (mapped to undefined); pass a positive integer
173	 *   to enforce a page size.
174	 */
175	export async function handleListKnowledge(
176	  ledgerRoot: string,
177	  params: KnowledgeListParams = {}
178	): Promise<Insight[]> {
179	  const manager = new KnowledgeStoreManager(ledgerRoot);
180	
181	  // Validate scope — reject any non-nullish string that is not a valid InsightScope value.
182	  // Absent scope (undefined) means "no filter" and is always allowed.
183	  let scope: 'global' | 'repository' | undefined;
184	  if (params.scope !== undefined) {
185	    const scopeResult = InsightScope.safeParse(params.scope);
186	    if (!scopeResult.success) {
187	      validationError(`Invalid scope value: '${params.scope}'. Must be 'global' or 'repository'.`);
188	    }
189	    scope = scopeResult.data;
190	  }
191	
192	  const category = params.category ?? undefined;
193	  const repository_name = params.repository_name ?? undefined;
194	
195	  // Split comma-separated tags; ignore empty segments.
196	  const tags =
197	    params.tags && params.tags.trim().length > 0
198	      ? params.tags
199	          .split(',')
200	          .map((t) => t.trim())
201	          .filter((t) => t.length > 0)
202	      : undefined;
203	
204	  // Coerce pagination params.
205	  const limitRaw = params.limit !== undefined ? Math.floor(Number(params.limit)) : NaN;
206	  const limit = !isNaN(limitRaw) && limitRaw > 0 ? limitRaw : undefined;
207	
208	  const offsetRaw = params.offset !== undefined ? Math.floor(Number(params.offset)) : NaN;
209	  const offset = !isNaN(offsetRaw) && offsetRaw >= 0 ? offsetRaw : 0;
210	
211	  if (params.query && params.query.trim().length > 0) {
212	    return manager.searchInsights(params.query.trim(), { scope, repository_name, category, tags, limit, offset });
213	  }
214	
215	  return manager.listInsights({ scope, category, tags, repository_name, limit, offset });
216	}
217	
218	// ---------------------------------------------------------------------------
219	// PATCH /api/knowledge/:id
220	// ---------------------------------------------------------------------------
221	
222	/**
223	 * Updates an existing knowledge insight identified by its numeric ID.
224	 *
225	 * Validates the raw ID string via `parseKnowledgeId` (throws VALIDATION_ERROR
226	 * for non-integer, zero, or floating-point strings). Validates the request body
227	 * via `KnowledgeUpdateBodySchema` (throws VALIDATION_ERROR for unknown fields or
228	 * type mismatches). Extracts `scope` and `repository_name` discriminator fields to
229	 * scope the update to the correct store.
230	 *
231	 * `superseded_by: null` in the body is mapped to `undefined` so the field is
232	 * cleared (removed) on the stored insight.
233	 *
234	 * Throws NOT_FOUND when no insight with the given ID exists in the specified scope.
235	 *
236	 * @param ledgerRoot  Absolute path to the central ledger root.
237	 * @param rawId       Raw ID string from the URL parameter (e.g. "42").
238	 * @param body        Parsed request body (any shape — validated here).
239	 * @returns The updated Insight.
240	 */
241	export async function handleUpdateKnowledge(
242	  ledgerRoot: string,
243	  rawId: string,
244	  body: unknown
245	): Promise<Insight> {
246	  const id = parseKnowledgeId(rawId);
247	
248	  const parseResult = KnowledgeUpdateBodySchema.safeParse(body);
249	  if (!parseResult.success) {
250	    validationError('Invalid knowledge update body.', parseResult.error.issues);
251	  }
252	
253	  const { scope, repository_name, superseded_by, ...rest } = parseResult.data;
254	
255	  // Map superseded_by: null → undefined so the field is cleared on the stored insight.
256	  const updates: Parameters<KnowledgeStoreManager['updateInsight']>[1] = {
257	    ...rest,
258	    ...(superseded_by === null ? { superseded_by: undefined } : superseded_by !== undefined ? { superseded_by } : {}),
259	  };
260	
261	  const manager = new KnowledgeStoreManager(ledgerRoot);
262	
263	  try {
264	    return await manager.updateInsight(id, updates, { scope, repository_name });
265	  } catch (err) {
266	    const msg = err instanceof Error ? err.message : String(err);
267	    if (msg.includes('not found')) {
268	      throw new ApiError('NOT_FOUND', 'Insight not found.');
269	    }
270	    throw err;
271	  }
272	}
273	
274	// ---------------------------------------------------------------------------
275	// DELETE /api/knowledge/:id
276	// ---------------------------------------------------------------------------
277	
278	/**
279	 * Deletes an existing knowledge insight identified by its numeric ID.
280	 *
281	 * Validates the raw ID string via `parseKnowledgeId` (throws VALIDATION_ERROR
282	 * for non-integer, zero, or floating-point strings). Requires `scope` as a
283	 * query parameter; when `scope === 'repository'`, `repository_name` is also required
284	 * (throws VALIDATION_ERROR if absent). Scopes the deletion to the correct store
285	 * to prevent accidental cross-scope deletion when the same numeric ID exists in
286	 * multiple stores.
287	 *
288	 * Throws NOT_FOUND when no insight with the given ID exists in the specified scope.
289	 *
290	 * `repository_name` is validated against `PROJECT_SLUG_REGEX` at this handler level
291	 * (after the presence check) before being forwarded to the storage layer. A malformed
292	 * slug throws `VALIDATION_ERROR` (HTTP 400) immediately, consistent with
293	 * `handleMoveKnowledge` and `handleUpdateKnowledge`.
294	 *
295	 * @param ledgerRoot      Absolute path to the central ledger root.
296	 * @param rawId           Raw ID string from the URL parameter (e.g. "42").
297	 * @param scope           Required scope query parameter ('global' or 'repository').
298	 * @param repository_name Required when scope is 'repository'; the repository name.
299	 * @returns `null` — consistent with other delete handlers.
300	 */

301	export async function handleDeleteKnowledge(
302	  ledgerRoot: string,
303	  rawId: string,
304	  scope: string | undefined,
305	  repository_name?: string
306	): Promise<null> {
307	  const id = parseKnowledgeId(rawId);
308	
309	  // Validate scope — required and must be a recognised InsightScope value.
310	  const scopeResult = InsightScope.safeParse(scope);
311	  if (!scopeResult.success) {
312	    validationError('scope query parameter is required and must be "global" or "repository".');
313	  }
314	  const validatedScope = scopeResult.data;
315	
316	  // repository_name is required when scope === 'repository'.
317	  if (validatedScope === 'repository' && !repository_name) {
318	    validationError('repository_name query parameter is required when scope is "repository".');
319	  }
320	
321	  // Validate repository_name format — must match PROJECT_SLUG_REGEX.
322	  if (repository_name && !PROJECT_SLUG_REGEX.test(repository_name)) {
323	    validationError('repository_name contains invalid characters. Use only alphanumerics, hyphens, and underscores.');
324	  }
325	
326	  const manager = new KnowledgeStoreManager(ledgerRoot);
327	
328	  try {
329	    await manager.deleteInsight(id, { scope: validatedScope, repository_name });
330	  } catch (err) {
331	    const msg = err instanceof Error ? err.message : String(err);
332	    if (msg.includes('not found')) {
333	      throw new ApiError('NOT_FOUND', 'Insight not found.');
334	    }
335	    throw err;
336	  }
337	
338	  return null;
339	}
340	
341	// ---------------------------------------------------------------------------
342	// POST /api/knowledge/:id/promote
343	// ---------------------------------------------------------------------------
344	
345	/**
346	 * Promotes a repository-scoped insight to global scope using the atomic
347	 * KnowledgeStoreManager.moveInsight() method.
348	 *
349	 * The returned insight is the newly created global-scoped copy — it has a
350	 * **different numeric ID** than the original (assigned by the global store's
351	 * `next_id` counter). The frontend must match by pre-promote ID, not the new ID.
352	 *
353	 * `repository_name` is validated against `PROJECT_SLUG_REGEX` at this handler level
354	 * (after the presence check) before being forwarded to the storage layer. A malformed
355	 * slug throws `VALIDATION_ERROR` (HTTP 400) immediately, consistent with
356	 * `handleMoveKnowledge` and `handleUpdateKnowledge`.
357	 *
358	 * @param ledgerRoot      Absolute path to the central ledger root.
359	 * @param rawId           Raw ID string from the URL parameter (e.g. "42").
360	 * @param scope           Source scope — must be "repository" (global insights cannot be promoted).
361	 * @param repository_name Required when scope is "repository"; the source repository name.
362	 * @returns The newly created global Insight.
363	 * @throws ApiError VALIDATION_ERROR if scope is not "repository", insight is already global,
364	 *   or repository_name fails PROJECT_SLUG_REGEX validation.
365	 * @throws ApiError NOT_FOUND if no matching insight exists in the specified scope.
366	 */
367	export async function handlePromoteKnowledge(
368	  ledgerRoot: string,
369	  rawId: string,
370	  scope: string | undefined,
371	  repository_name?: string
372	): Promise<Insight> {
373	  const id = parseKnowledgeId(rawId);
374	
375	  // Validate scope — must be 'repository' (global insights are already global).
376	  const scopeResult = InsightScope.safeParse(scope);
377	  if (!scopeResult.success) {
378	    validationError('scope query parameter is required and must be "global" or "repository".');
379	  }
380	  const validatedScope = scopeResult.data;
381	
382	  if (validatedScope === 'global') {
383	    validationError('Insight is already global and cannot be promoted.');
384	  }
385	
386	  // repository_name is required when scope === 'repository'.
387	  if (!repository_name) {
388	    validationError('repository_name query parameter is required when scope is "repository".');
389	  }
390	
391	  // Validate repository_name format — must match PROJECT_SLUG_REGEX.
392	  if (!PROJECT_SLUG_REGEX.test(repository_name)) {
393	    validationError('repository_name contains invalid characters. Use only alphanumerics, hyphens, and underscores.');
394	  }
395	
396	  const manager = new KnowledgeStoreManager(ledgerRoot);
397	
398	  try {
399	    return await manager.moveInsight(
400	      id,
401	      { scope: validatedScope, repository_name },
402	      'global'
403	    );
404	  } catch (err) {
405	    const msg = err instanceof Error ? err.message : String(err);
406	    if (msg.toLowerCase().includes('not found')) {
407	      throw new ApiError('NOT_FOUND', 'Insight not found.');
408	    }
409	    throw err;
410	  }
411	}
412	
413	// ---------------------------------------------------------------------------
414	// POST /api/knowledge/:id/move
415	// ---------------------------------------------------------------------------
416	
417	/**
418	 * Moves an insight from one scope/repository to a different repository using the
419	 * atomic KnowledgeStoreManager.moveInsight() method.
420	 *
421	 * Supports two move variants:
422	 * - global → repository: moves the global insight into a named repository store
423	 * - repository → repository: moves a repository insight to a different repository
424	 *
425	 * The returned insight is the newly created copy — it has a **different numeric
426	 * ID** (assigned by the target store's `next_id` counter).
427	 *
428	 * @param ledgerRoot  Absolute path to the central ledger root.
429	 * @param rawId       Raw ID string from the URL parameter (e.g. "42").
430	 * @param body        Parsed request body (validated against KnowledgeMoveBodySchema).
431	 * @returns The newly created Insight in the target repository store.
432	 * @throws ApiError VALIDATION_ERROR when source and destination are identical, body is invalid,
433	 *   or the destination name fails PROJECT_SLUG_REGEX.
434	 * @throws ApiError NOT_FOUND when no matching insight exists in the source scope.
435	 */
436	export async function handleMoveKnowledge(
437	  ledgerRoot: string,
438	  rawId: string,
439	  body: unknown
440	): Promise<Insight> {
441	  const id = parseKnowledgeId(rawId);
442	
443	  const parseResult = KnowledgeMoveBodySchema.safeParse(body);
444	  if (!parseResult.success) {
445	    validationError('Invalid knowledge move body.', parseResult.error.issues);
446	  }
447	
448	  const { source_scope, source_repository_name, repository_name } = parseResult.data;
449	
450	  // Require source_repository_name when source_scope is 'repository'.
451	  if (source_scope === 'repository' && !source_repository_name) {
452	    validationError('source_repository_name is required when source_scope is "repository".');
453	  }
454	
455	  // Validate that source and destination are not identical.
456	  // global → repository always changes scope, so no identity check is needed for that case.
457	  if (source_scope === 'repository' && source_repository_name === repository_name) {
458	    validationError('Source and destination repository are identical; nothing to move.');
459	  }
460	
461	  const manager = new KnowledgeStoreManager(ledgerRoot);
462	
463	  try {
464	    return await manager.moveInsight(
465	      id,
466	      { scope: source_scope, repository_name: source_repository_name },
467	      'repository',
468	      repository_name
469	    );
470	  } catch (err) {
471	    const msg = err instanceof Error ? err.message : String(err);
472	    if (msg.toLowerCase().includes('not found')) {
473	      throw new ApiError('NOT_FOUND', 'Insight not found.');
474	    }
475	    throw err;
476	  }
477	}

